import Foundation
import ValseCore

/// Bundled royalty-free music + sound-effect library (AU-001 / AU-002 / AU-025): real recordings released under
/// CC0 / public domain, safe to publish on Instagram, TikTok, YouTube (commercial use, no attribution, no claims).
///
/// - Metadata (license, source, author, BPM, key, beats, waveform peaks, similarity features) lives in the
///   committed manifest `Resources/ContentLibrary/content_manifest.json`, generated by `scripts/fetch_music_pack.sh`.
/// - Audio files (AAC .m4a) are never committed: the fetch script downloads, verifies and transcodes them into a
///   cache, `scripts/build_app.sh` copies them into `Valse.app/Contents/Resources/Content`. At runtime nothing
///   is downloaded: `directory` resolves the bundle (or `VALSE_CONTENT_DIR`, or the developer cache).
public struct ContentItem: Codable, Sendable, Identifiable, Hashable {
    public enum Kind: String, Codable, Sendable { case music, sfx }

    public struct License: Codable, Sendable, Hashable {
        /// SPDX id ("CC0-1.0") or "LicenseRef-PublicDomain" (Wikimedia Commons public-domain templates).
        public var id: String
        public var name: String
        public var url: String
        /// Page whose text was checked by the fetch script (license statement for this item / pack).
        public var evidence: String
        /// ISO date of the check.
        public var verified: String
    }

    public struct Source: Codable, Sendable, Hashable {
        /// "FreePD.com", "Free Music Archive", "Kenney", "OpenGameArt", "Wikimedia Commons".
        public var name: String
        /// Human page for the item (track page, pack page, Commons file page).
        public var page: String
        /// Exact URL the original file was downloaded from.
        public var download: String
        public var author: String
        /// ISO date the original was fetched.
        public var retrieved: String
        public var published: String?
        /// Pack / album the item comes from.
        public var pack: String?
        /// Path inside the pack archive.
        public var path: String?
        public var originalSha256: String
    }

    public var id: String
    public var kind: Kind
    /// Work title (proper name, not localized) — music only; sound effects use `name` + `n`.
    public var title: String
    public var artist: String
    /// Rail category ("vlog", "lofi" … / sfx "transition", "ui" …), localized via `music.cat.*` / `sfx.category.*`.
    public var category: String
    public var mood: String?
    public var tags: [String]
    /// Sound effects: localized base name key suffix (`sfx.n.<name>`) and its number ("Click 3").
    public var name: String?
    public var n: Int?
    /// Path relative to the content directory ("music/<id>.m4a").
    public var file: String
    public var bytes: Int
    public var sha256: String
    public var license: License
    public var source: Source

    // Analysis (ContentAnalyzer)
    public var duration: Double?
    public var bpm: Double?
    public var key: String?
    /// Every beat (seconds); `strongPhase` = index parity of the stronger beats (CapCut "Beats 1").
    public var beats: [Double]?
    public var strongPhase: Int?
    public var loudness: Double?
    /// Waveform peaks 0…255 (preview strip before decoding).
    public var peaks: [Int]?
    public var features: [Float]?

    public var strongBeats: [Double] {
        guard let b = beats else { return [] }
        let p = strongPhase ?? 0
        return stride(from: p, to: b.count, by: 2).map { b[$0] }
    }
}

public struct ContentManifest: Codable, Sendable {
    public var version: Int
    public var featureVersion: Int
    public var generated: String
    public var stats: [String: ContentFeatureStats]
    public var items: [ContentItem]

    public init(version: Int = 1, featureVersion: Int = AudioFeatures.version, generated: String,
                stats: [String: ContentFeatureStats] = [:], items: [ContentItem]) {
        self.version = version; self.featureVersion = featureVersion; self.generated = generated
        self.stats = stats; self.items = items
    }

    /// One item per line (readable diffs), keys sorted.
    public func encoded() throws -> Data {
        let enc = JSONEncoder()
        enc.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        var head = ContentManifest(version: version, featureVersion: featureVersion, generated: generated, stats: stats, items: [])
        head.items = []
        let headJSON = String(decoding: try enc.encode(head), as: UTF8.self)
        let lines = try items.map { String(decoding: try enc.encode($0), as: UTF8.self) }
        // splice the item lines into `"items":[]`
        let body = headJSON.replacingOccurrences(of: "\"items\":[]", with: "\"items\":[\n" + lines.joined(separator: ",\n") + "\n]")
        return Data((body + "\n").utf8)
    }
}

public enum ContentLibrary {
    /// Licenses allowed in the bundled library: no attribution, commercial use, no share-alike, no platform limits.
    public static let allowedLicenses: Set<String> = ["CC0-1.0", "LicenseRef-PublicDomain"]

    /// Music rail categories, in display order.
    public static let musicCategories = ["vlog", "upbeat", "chill", "lofi", "cinematic", "corporate", "emotional", "hiphop",
                                         "acoustic", "electronic", "funny", "jazz"]
    public static let sfxCategories = ["transition", "ui", "notification", "impact", "cartoon", "crowd", "tech", "money",
                                       "stings", "foley", "nature", "scifi"]
    public static let moods = ["happy", "chill", "energetic", "epic", "romantic", "dreamy", "sad", "tense", "inspiring", "playful", "groovy"]

    /// Tests / tools can swap the manifest.
    nonisolated(unsafe) public static var manifestOverride: ContentManifest?
    nonisolated(unsafe) public static var directoryOverride: URL?

    public static let bundledManifestURL: URL? = EngineResources.bundle.url(forResource: "content_manifest", withExtension: "json",
                                                                           subdirectory: "ContentLibrary")
        ?? EngineResources.bundle.url(forResource: "content_manifest", withExtension: "json")

    private static let loaded: ContentManifest = {
        guard let u = bundledManifestURL, let d = try? Data(contentsOf: u) else {
            EngineLog.error("content manifest missing from the engine bundle")
            return ContentManifest(generated: "", items: [])
        }
        do { return try JSONDecoder().decode(ContentManifest.self, from: d) } catch {
            EngineLog.error("content manifest unreadable: \(error)")
            return ContentManifest(generated: "", items: [])
        }
    }()

    public static var manifest: ContentManifest { manifestOverride ?? loaded }
    public static var items: [ContentItem] { manifest.items }
    public static var music: [ContentItem] { items.filter { $0.kind == .music } }
    public static var sfx: [ContentItem] { items.filter { $0.kind == .sfx } }

    private static let byID: [String: ContentItem] = Dictionary(loaded.items.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })
    public static func item(id: String) -> ContentItem? {
        manifestOverride == nil ? byID[id] : manifestOverride!.items.first { $0.id == id }
    }

    /// Developer cache written by scripts/fetch_music_pack.sh (`VALSE_CONTENT_CACHE`, default
    /// ~/Library/Caches/ValseDev/content); its `out/` folder mirrors the bundle's Content folder.
    public static var developerCache: URL {
        if let p = ProcessInfo.processInfo.environment["VALSE_CONTENT_CACHE"], !p.isEmpty { return URL(fileURLWithPath: p) }
        return FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Caches/ValseDev/content", isDirectory: true)
    }

    /// Candidate folders, most specific first.
    static var candidates: [URL] {
        var c: [URL] = []
        if let d = directoryOverride { c.append(d) }
        if let p = ProcessInfo.processInfo.environment["VALSE_CONTENT_DIR"], !p.isEmpty { c.append(URL(fileURLWithPath: p)) }
        if let r = Bundle.main.resourceURL { c.append(r.appendingPathComponent("Content", isDirectory: true)) }
        c.append(developerCache.appendingPathComponent("out", isDirectory: true))
        return c
    }

    private static let resolved: URL? = resolve()

    static func resolve() -> URL? {
        let probe = items.first?.file ?? "music"
        return candidates.first { FileManager.default.fileExists(atPath: $0.appendingPathComponent(probe).path) }
    }

    /// Folder holding the audio files (nil = library not installed, e.g. a clean checkout without the fetch).
    public static var directory: URL? { directoryOverride ?? resolved }

    public static func url(for item: ContentItem) -> URL? { directory?.appendingPathComponent(item.file) }

    public static func isAvailable(_ item: ContentItem) -> Bool {
        guard let u = url(for: item) else { return false }
        return FileManager.default.fileExists(atPath: u.path)
    }

    /// Items whose file is installed (cached per kind; the bundle never changes at runtime).
    public static var availableMusic: [ContentItem] { available.music }
    public static var availableSFX: [ContentItem] { available.sfx }
    private static let available: (music: [ContentItem], sfx: [ContentItem]) = {
        let ok = loaded.items.filter { isAvailable($0) }
        return (ok.filter { $0.kind == .music }, ok.filter { $0.kind == .sfx })
    }()

    /// Total size of the library audio files (bytes).
    public static var totalBytes: Int { items.reduce(0) { $0 + $1.bytes } }

    /// License problems of an item (empty = OK): allowed license, provenance recorded, analysis present.
    public static func validate(_ i: ContentItem) -> [String] {
        var p: [String] = []
        if !allowedLicenses.contains(i.license.id) { p.append("license \(i.license.id) not allowed") }
        if i.license.evidence.isEmpty || i.license.verified.isEmpty { p.append("license not verified") }
        if !i.license.url.hasPrefix("https://") { p.append("license url") }
        if i.source.author.isEmpty { p.append("no author") }
        if !i.source.download.hasPrefix("https://") || !i.source.page.hasPrefix("https://") { p.append("source url") }
        if i.source.retrieved.count != 10 { p.append("retrieved date") }
        if i.source.originalSha256.count != 64 || i.sha256.count != 64 { p.append("checksum") }
        if !i.file.hasSuffix(".m4a") { p.append("file type") }
        if i.duration == nil || (i.duration ?? 0) <= 0 { p.append("duration") }
        if i.kind == .music {
            if i.bpm == nil || i.beats?.isEmpty != false { p.append("beats") }
            if i.mood == nil { p.append("mood") }
            if !musicCategories.contains(i.category) { p.append("category \(i.category)") }
        } else {
            if i.name == nil { p.append("sfx name") }
            if !sfxCategories.contains(i.category) { p.append("category \(i.category)") }
        }
        if i.features?.count != AudioFeatures.dimension { p.append("features") }
        return p
    }
}

/// "Similar sounds" (AU-025): nearest neighbours in the normalised feature space.
public enum ContentSimilarity {
    public struct Match: Sendable, Equatable {
        public let item: ContentItem
        public let score: Float
    }

    /// Items of `kind` most similar to the raw feature vector `v` (best first, `exclude` skipped).
    public static func similar(toFeatures v: [Float], kind: ContentItem.Kind, exclude: String? = nil, limit: Int = 20,
                               in items: [ContentItem]? = nil) -> [Match] {
        let m = ContentLibrary.manifest
        guard let stats = m.stats[kind.rawValue], v.count == stats.mean.count else { return [] }
        let q = stats.embed(v)
        let pool = (items ?? ContentLibrary.items).filter { $0.kind == kind && $0.id != exclude }
        var out: [Match] = []
        for i in pool {
            guard let f = i.features, f.count == q.count else { continue }
            let e = stats.embed(f)
            var dot: Float = 0
            for k in 0..<q.count { dot += q[k] * e[k] }
            out.append(Match(item: i, score: dot))
        }
        return Array(out.sorted { $0.score != $1.score ? $0.score > $1.score : $0.item.id < $1.item.id }.prefix(limit))
    }

    /// Items most similar to a library item (same kind).
    public static func similar(to item: ContentItem, limit: Int = 20, in items: [ContentItem]? = nil) -> [Match] {
        guard let f = item.features else { return [] }
        return similar(toFeatures: f, kind: item.kind, exclude: item.id, limit: limit, in: items)
    }

    /// Kind to compare a clip's audio against: long excerpts are music, short ones sound effects.
    public static func kind(forDuration seconds: Double) -> ContentItem.Kind { seconds >= 8 ? .music : .sfx }

    /// Features of an arbitrary file range (e.g. the audio of a selected clip). CPU-heavy: call off the main thread.
    public static func features(url: URL, range: TimeRange?) async throws -> [Float] {
        let (r, _, _) = try await AudioFeatures.analyze(url: url, range: range, maxSeconds: 90)
        return r.vector
    }
}
